import{z as d,x as A,o,c as B,q as t,j as l,D as e,d as E,s as i,S as s,b as r}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"日志粒度","description":"","frontmatter":{"title":"日志粒度","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/logging-granularity.md","filePath":"cs/logging-granularity.md","lastUpdated":1791063341000}'),p={name:"cs/logging-granularity.md"};function g(c,a,u,C,h,m){const n=A("Mermaid");return o(),B("div",null,[a[2]||(a[2]=t('<h1 id="日志粒度" tabindex="-1">日志粒度 <a class="header-anchor" href="#日志粒度" aria-label="Permalink to &quot;日志粒度&quot;">​</a></h1><div class="epigraph"><p>生理日志记页内字节差，redo 快、undo 要逻辑；逻辑日志记「插入键 k」，重放走索引代码。粒度决定恢复 CPU、交叉与复制形态。</p><footer>—— 据 Gray and Reuter；Mohan 生理日志；逻辑复制谱系</footer></div><p><a href="/cs/fuzzy-checkpoint">上一课</a>钉了检查点快照。本课不刷脏。缺口是一条日志记什么：整页（page logging）浪费带宽；字节级生理；操作级逻辑；行级。主干 WAL 未选粒度。进阶对照，影子分页下一课是另一恢复族。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>生理（physiological）：在页号已知的页上应用字节差或槽操作，不重走 B+ 查找。redo 快、依赖 pageLSN。逻辑：<code>insert into T values (...)</code>，重放必须可再执行查询代码，页布局可变，适合逻辑复制与异构引擎，redo 慢且要处理非确定性。混合：redo 生理、undo 逻辑（ARIES）。</p><p>缺口是<strong>交叉</strong>：同一页上未提交与已提交更新，生理 undo 用补偿；逻辑 undo 用逆操作。粒度越粗（整页），写放大越大、并发更互斥。</p><p><span class="marginnote">Gray 对 logging 粒度。MySQL binlog 行/语句、Postgres WAL 生理+logical decoding 是产品线。本课分类。</span></p><p><span class="marginnote">「生理日志」这个词别被吓住：它指「记在某一具体页上的最小改动」，重放时翻到那页照抄即可，不必重新走一遍 B+ 树查找；「逻辑」日志记的则是「插入键 k」这类操作语义，重放要把整条执行路径再跑一遍——快慢差距就从这里来。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>OLTP 本地恢复：生理 redo + CLR。跨版本升级、逻辑备库：从生理 WAL 解码成行（logical decoding）或直接逻辑日志。语句级逻辑：<code>UPDATE t SET x=x+1</code> 在重放时非确定性若有触发器——行级更安全。</p><p>压缩：redo 差量。加密：日志也要 TDE，否则数据页加密无意义。</p><p><span class="marginnote">数字实例：更新一个 8 KB 页里的 20 字节——整页日志要记 8 KB，生理差量只记约 20 字节，写放大差约 400 倍；若该库每秒 1 万笔这样的更新，日志带宽就从约 80 MB/s 掉到 0.2 MB/s。粒度直接决定恢复与复制的带宽账单。</span></p><p><span class="marginnote">初学者容易以为逻辑日志「更高级」就该全用它。实际上 <code>UPDATE t SET x=x+1</code> 这类语句在备库重放时，可能因触发器、时间函数、非确定计划得到不同结果；行级「改前/改后」值才保证处处可复现——这正是跨引擎复制偏爱行级的原因。</span></p>',13)),(o(),l(s,null,{default:e(()=>[i(n,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20PAGE%5B%22%E6%95%B4%E9%A1%B5%E6%97%A5%E5%BF%97%22%5D%20--%3E%20FAT%5B%22%E5%B8%A6%E5%AE%BD%E5%A4%A7%22%5D%0A%20%20PHYS%5B%22%E7%94%9F%E7%90%86%3A%20%E9%A1%B5%E5%86%85%E5%B7%AE%22%5D%20--%3E%20ARIES%5B%22ARIES%20redo%22%5D%0A%20%20LOGI%5B%22%E9%80%BB%E8%BE%91%3A%20%E6%93%8D%E4%BD%9C%20%2F%20%E8%A1%8C%22%5D%20--%3E%20CDC%5B%22%E5%A4%8D%E5%88%B6%E4%B8%8E%E5%BC%82%E6%9E%84%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[E("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,"并行重放的能力也随粒度变化：生理记录自带页号，可以切开并行；逻辑操作彼此纠缠，只能排队或粗粒度分区。",-1)),(o(),l(s,null,{default:e(()=>[i(n,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20REC%5B%22%E5%B4%A9%E6%BA%83%E6%88%96%E5%A4%87%E5%BA%93%E9%87%8D%E6%94%BE%22%5D%20--%3E%20PHYS%5B%22%E7%94%9F%E7%90%86%E6%97%A5%E5%BF%97%EF%BC%9A%E6%AF%8F%E6%9D%A1%E5%B8%A6%E9%A1%B5%E5%8F%B7%22%5D%0A%20%20PHYS%20--%3E%20PAR%5B%22%E6%8C%89%E9%A1%B5%E5%88%87%E5%BC%80%EF%BC%8C%E5%A4%9A%E4%B8%AA%20worker%20%E5%B9%B6%E8%A1%8C%22%5D%0A%20%20REC%20--%3E%20LOGI%5B%22%E9%80%BB%E8%BE%91%E6%97%A5%E5%BF%97%EF%BC%9A%E6%93%8D%E4%BD%9C%E8%A6%81%E6%8C%89%E5%BA%8F%E6%89%A7%E8%A1%8C%22%5D%0A%20%20LOGI%20--%3E%20SEQ%5B%22%E5%B8%B8%E5%8D%95%E7%BA%BF%E7%A8%8B%EF%BC%8C%E6%88%96%E6%8C%89%E8%A1%A8%E5%88%86%E5%8C%BA%E9%98%B2%E5%86%B2%E7%AA%81%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=t('<p>组提交把多粒度记录一起刷。并行 redo 按页分区要求生理带页号。逻辑重放常单线程或按表分区，冲突检测像 OCC。</p><p>与 Calvin：输入日志是事务级逻辑，执行再产生理——两层。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲影子页对照。也不把 binlog 格式当标准。RTO 依赖粒度：生理 redo 吞吐高。</p><p>后课默认：单机恢复用生理；跨引擎用逻辑行。影子分页：写新页，根指针切换，对照 WAL 原地更新。</p><p>粒度是恢复与复制的同一设计轴。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>生理 redo 快、绑页；逻辑可移植、重放重。</li><li>ARIES 常用 redo 生理 + undo 逻辑。</li><li>影子分页对照下一课。</li><li>出处：Gray and Reuter；ARIES；逻辑解码实践。</li></ul>',8))])}const T=d(p,[["render",g]]);export{_ as __pageData,T as default};
